    "snippet": "l continue to seek to conclude an international convention on global climate change in time for its signing at the 1992 United Nations Conference on Environment and Development in Brazil. In our view, such a convention must be comprehensive in scope, addressing all sources and sinks of greenhouse gases, adaptation as well as mitigation measures, and continued scientific and economic research and policy responses. The United States is committed to a series of domestic actions that have many benefits such as curbing air pollution, conse",
