    "extraction": "govinfo-granule-html",
    "snippet": "hile I'm President to build stronger relations with South America. I've been down there; I've talked endlessly to the Presidents of the various countries. Just the other day, Gus, Carlos Andres Perez of Venezuela was in. He doesn't benefit from a free trade agreement with Mexico, but he said: You cannot let this fail. The signal that this would send through our part of the world would just be unconscionable. And so, I am committed to this. And I'm committed to it not just because it's good for Mexico. I'm the President of the United S",
