    "snippet": "e faith.'' Remember Lincoln, going to his knees in times of trial in the Civil War and all that stuff. You can't be. And we are blessed. So don't feel sorry for--don't cry for me, Argentina. We've got problems out there, and I am blessed by good health, strong health. Geez, you get the flu, and they make it into a Federal case. [Laughter] Anyway, that goes with the territory. I'm not asking for sympathy, I just wanted you to know that I never felt more up for the charge. I wish I could tuck each one of you for 10 minutes into that car",
