    "extraction": "govinfo-granule-html",
    "snippet": "tend the United Nations Conference on the Environment and Development? The President. Her question was whether I plan to attend the United Nations conference which will be held in Brazil on the environment. We're talking about that right now. The problem is it comes at a time when we've got a relatively hot political year here. But the United States must lead, and I have not told President Collor of Brazil yet whether I can do it. I'm talking to other world leaders as to whether they're attending. Bill Reilly, who is doing a superb jo",
