    "pageLink": "https://www.govinfo.gov/content/pkg/PPP-1992-book1/pdf/PPP-1992-book1-doc-pg333.pdf",
    "extraction": "govinfo-granule-html",
    "snippet": "do it. The Devil made me do it. [Laughter] Q. Are you thinking about visiting South America? The President. I hope I can get down there again. I know I will sometime. Q. ----visit Ecuador. The President. I've been there. As V.P., I was down there. I've been to Colombia several times. Q. ----apologize to him? The President. I apologized for getting the whole thing messed up. I don't know what happened. I told them all--I mean, I'm afraid I know what happened. It wasn't very nice, but that's the way it is. Q. Mr. President, was Mr. Fuji",
    "sourceCollection": {
      "name": "Public Papers of the Presidents of the United States: George H. W. Bush",
      "url": "https://www.govinfo.gov/app/collection/ppp/president-41_Bush,%20George%20H.%20W."
    },
    "sourceNote": "Source: Public Papers of the Presidents of the United States: George H. W. Bush, 1992, Book I, February 27, 1992, \"Exchange With Reporters Following the News Conference in San Antonio\", p. 333. GovInfo, Government Publishing Office."
