    "extraction": "govinfo-granule-html",
    "snippet": "tes feeling at home, just as we are awaiting your visit in Nicaragua. President Bush. We weren't sure our Assistant Secretary, Bernie Aronson, was going to make it. He was down in Peru. He can tell us. He can tell us, yes. He's coming over. He's going to wait for these cameras. Manuel Noriega Verdict Q. Mr. President, your reaction to the Noriega verdict? President Bush. Noriega was convicted, I think, on 8 out of 10 counts. Well, I think [[Page 574]] it's a major victory against the drug lords. We're going to continue the fight again",
