    "extraction": "govinfo-granule-html",
    "snippet": "ned to keep working to promote and protect democracy in Latin America. Recently, we've been working closely with our partners in the hemisphere to defend democracy under attack in Venezuela, Haiti, and Peru. In Cuba we envision a new birth of freedom and democracy, and that day cannot be far off. I expect one day soon, after the inevitable fall of the Castro dictatorship, to be the first President of the United States to visit the free soil of Cuba. Also vital is liberating the markets of the Western Hemisphere. I want to create a Nor",
