    "extraction": "govinfo-granule-html",
    "snippet": "1(a) of the Marine Mammal Protection Act (MMPA), the Secretary of Commerce certified to me that a ban on the importation of yellowfin tuna and yellowfin tuna products from Canada, Colombia, Malaysia, the Netherlands Antilles, Singapore, Spain, and the United Kingdom has been in effect since January 31, 1992. This ban is the result of an order issued by the U.S. District Court for the Northern District of California, which the Administration has appealed. By the terms of the MMPA, such certification is deemed to be a certification for",
