    "extraction": "govinfo-granule-html",
    "snippet": "more opportunity and thus more jobs. It begins with an aggressive strategy to open new markets, so that ``Made in America'' is understood in any language from Lima, Ohio, to Lima, Peru, and beyond. Some will say that the American worker isn't up to it. And I say: Look, give our workers a level playing field, and they will outperform any worker in the world, anyplace, anywhere, anytime. I learned this myself. Thank God I spent some time in the private sector. Half my adult life was in the private sector, and half in public service. But",
