    "snippet": "ation, and I'm not suggesting that alone can get the job done, and then redoubling our efforts on interdiction. We have some good people that are working with us in Latin America. Gaviria in Colombia has done a good job on it. We're trying to work with Peru and Bolivia on this. But that's a major part of it. And we're using the military much more than we did to try to interdict the flow of narcotics coming into this country. But once again, here's an area where we really do have to back up those that are out on the streets, our people",
