    "snippet": "ur agriculture, particularly. I want to continue to work after we get this NAFTA agreement ratified this coming year. I want to get one with Eastern Europe. I want to get one with Chile. Free and fair trade is the answer, not protection. As I say, we've had tough economic times, and it's exports that have saved us, exports that have built---- Ms. Simpson. Governor Clinton. Governor Clinton. I'd like to answer the question, because I've actually been a Governor for 12 years, so I've known a lot of people who have lost their jobs becaus",
