    "extraction": "govinfo-granule-html",
    "snippet": "rcent. The addictive drug use, regrettably, is going the wrong way. Back the law enforcement people; do better in interdiction, although we've made some great strides working with Colombia, Peru, and all of these countries. And then back up the law enforcement people with tougher, not weaker but tougher, anticrime legislation that puts these real dealers away for a long, long time, no appeals, not getting them out early. He's trying to get me to do this quicker, but that's a quick and dirty answer. And education, education and rehabil",
