    "extraction": "govinfo-granule-html",
    "snippet": "e're going to need special programs. We've got programs in the Caribbean for those countries, Caribbean Basin Initiative. We've got a debt forgiveness program that has helped move Argentina and Brazil and other countries towards democracy. Many countries, 43 more countries have become democratic since I've been President, 43. Cuba will be the next one, I hope. But it's not going to require a lot of Government aid. Everybody hates foreign aid. It's not going to require that. It's going to require investment. These are industrious peopl",
