    "snippet": "thank you all for coming. I'm delighted to see so many people here who care so deeply about the forests. And first I want to greet and welcome the representatives from Belize and Brazil, Ghana, Guatemala, Indonesia, Mexico, Papua New Guinea, and Russia. And I congratulate you on the progress that your countries are making on forest management. We're delighted to be able to work with you on this important effort. It's good to see the cochairs of the effort, Bill Reilly, our EPA Administrator, and then Boyden Gray, my General Counsel h",
